const CACHE_NAME="pwa-cache-v1",ASSETS_TO_CACHE=["index.html","styles.min.css","script.min.js","app.min.js","og-imagen.png"];self.addEventListener("install",e=>{e.waitUntil(caches.open("pwa-cache-v1").then(e=>e.addAll(ASSETS_TO_CACHE)))}),self.addEventListener("fetch",e=>{e.respondWith(caches.match(e.request).then(t=>t||fetch(e.request)))});